import { __experimentalSpacingSizesControl as SpacingSizesControl } from '@wordpress/block-editor';
import { useState } from '@wordpress/element';

function Example() {
  const [ sides, setSides ] = useState( {
    top: '0px',
    right: '0px',
    bottom: '0px',
    left: '0px',
  } );

  return (
    <SpacingSizesControl
      values={ sides }
      onChange={ setSides }
      label="Sides"
    />
  );
}
